sys_script.script:
(function executeRule(current, previous /* null when async */) {

    var status = current.getValue('insight_status');
    var reviewedBy = current.getValue('reviewed_by');
    var reviewNotes = current.getValue('review_notes');

    /*
     * New status does not require review information.
     */
    if (status == 'New') {
        return;
    }

    /*
     * Every status after New requires Reviewed By.
     */
    if (gs.nil(reviewedBy)) {

        gs.addErrorMessage(
            'Reviewed By is required when Insight Status is ' +
            status + '.'
        );

        current.setAbortAction(true);
        return;
    }

    /*
     * Rejected and Resolved require review notes
     * to provide an audit explanation.
     */
    if ((status == 'Rejected' || status == 'Resolved') &&
        gs.nil(reviewNotes)) {

        gs.addErrorMessage(
            'Review Notes are required when Insight Status is ' +
            status + '.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
